create schema if not exists hospitality;
revoke all on schema hospitality from anon, authenticated;
grant usage on schema hospitality to service_role;

create table hospitality.owners (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),user_id uuid references vgroup.users(id) on delete set null,full_name text not null,email text,phone text,tax_id text,status text not null default 'active' check (status in ('active','suspended','archived')),archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_unit_id,email));
create table hospitality.properties (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),owner_id uuid not null references hospitality.owners(id),name text not null,property_type text not null default 'apartment',address_line1 text,address_line2 text,city text,country text not null default 'EG',timezone text not null default 'Africa/Cairo',bedrooms integer not null default 0 check (bedrooms>=0),bathrooms numeric(4,1) not null default 0 check (bathrooms>=0),max_guests integer not null default 1 check (max_guests>0),status text not null default 'active' check (status in ('active','maintenance','inactive','archived')),archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table hospitality.assets (id uuid primary key default gen_random_uuid(),property_id uuid not null references hospitality.properties(id) on delete cascade,name text not null,category text,serial_number text,purchase_date date,purchase_cost numeric(18,2) check (purchase_cost is null or purchase_cost>=0),condition text not null default 'good',notes text,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table hospitality.vendors (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),name text not null,category text,email text,phone text,tax_id text,rating numeric(3,2) check (rating is null or (rating>=0 and rating<=5)),status text not null default 'active' check (status in ('active','inactive','archived')),archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table hospitality.expense_categories (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),code text not null,name text not null,owner_chargeable boolean not null default true,active boolean not null default true,created_at timestamptz not null default now(),unique(business_unit_id,code));
create table hospitality.channel_connections (id uuid primary key default gen_random_uuid(),property_id uuid not null references hospitality.properties(id) on delete cascade,channel text not null check (channel in ('airbnb','booking','direct','other')),external_listing_id text not null,status text not null default 'pending' check (status in ('pending','connected','error','disabled')),last_sync_at timestamptz,last_error text,token_ref text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(channel,external_listing_id));
create table hospitality.reservations (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),property_id uuid not null references hospitality.properties(id),channel_connection_id uuid references hospitality.channel_connections(id) on delete set null,external_reservation_id text,source text not null default 'direct',guest_name text not null,guest_email text,guest_phone text,check_in date not null,check_out date not null,guests integer not null default 1 check (guests>0),currency text not null default 'EGP',gross_amount numeric(18,2) not null default 0 check (gross_amount>=0),platform_fee numeric(18,2) not null default 0 check (platform_fee>=0),company_commission numeric(18,2) not null default 0 check (company_commission>=0),net_owner_amount numeric(18,2) not null default 0,status text not null default 'confirmed' check (status in ('pending','confirmed','checked_in','checked_out','cancelled','no_show')),archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check (check_out>check_in),unique(source,external_reservation_id));
create table hospitality.invoices (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),property_id uuid references hospitality.properties(id),owner_id uuid references hospitality.owners(id),vendor_id uuid references hospitality.vendors(id),expense_category_id uuid references hospitality.expense_categories(id),invoice_number text,invoice_type text not null check (invoice_type in ('owner_charge','vendor_bill','platform_fee','company_fee','other')),currency text not null default 'EGP',subtotal numeric(18,2) not null default 0,tax numeric(18,2) not null default 0,total numeric(18,2) not null default 0,issued_at date not null default current_date,due_at date,status text not null default 'draft' check (status in ('draft','pending_approval','approved','paid','rejected','void')),approved_by uuid references vgroup.users(id),approved_at timestamptz,attachment_url text,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check (subtotal>=0 and tax>=0 and total>=0));
create table hospitality.work_orders (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),property_id uuid not null references hospitality.properties(id),vendor_id uuid references hospitality.vendors(id),title text not null,description text,priority text not null default 'normal' check (priority in ('low','normal','high','urgent')),status text not null default 'open' check (status in ('open','assigned','in_progress','waiting_approval','completed','cancelled')),estimated_cost numeric(18,2) not null default 0 check (estimated_cost>=0),actual_cost numeric(18,2) not null default 0 check (actual_cost>=0),before_photo_urls jsonb not null default '[]'::jsonb,after_photo_urls jsonb not null default '[]'::jsonb,requested_by uuid references vgroup.users(id),approved_by uuid references vgroup.users(id),completed_at timestamptz,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table hospitality.purchase_orders (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),vendor_id uuid not null references hospitality.vendors(id),property_id uuid references hospitality.properties(id),work_order_id uuid references hospitality.work_orders(id),po_number text,currency text not null default 'EGP',total numeric(18,2) not null default 0 check (total>=0),status text not null default 'draft' check (status in ('draft','pending_approval','approved','ordered','received','cancelled')),approved_by uuid references vgroup.users(id),approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table hospitality.inventory_items (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),property_id uuid references hospitality.properties(id),sku text not null,name text not null,unit text not null default 'unit',quantity numeric(18,3) not null default 0,reorder_level numeric(18,3) not null default 0,unit_cost numeric(18,2) not null default 0 check (unit_cost>=0),archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_unit_id,sku));
create table hospitality.inventory_movements (id uuid primary key default gen_random_uuid(),item_id uuid not null references hospitality.inventory_items(id),movement_type text not null check (movement_type in ('in','out','adjustment')),quantity_delta numeric(18,3) not null,reason text,related_work_order_id uuid references hospitality.work_orders(id),created_by uuid references vgroup.users(id),created_at timestamptz not null default now(),check (quantity_delta<>0));
create table hospitality.contracts (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),owner_id uuid references hospitality.owners(id),property_id uuid references hospitality.properties(id),contract_type text not null,version integer not null default 1 check (version>0),starts_at date,ends_at date,status text not null default 'draft' check (status in ('draft','sent','signed','active','expired','terminated','archived')),document_url text,signed_at timestamptz,signed_by text,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check (ends_at is null or starts_at is null or ends_at>=starts_at));
create table hospitality.owner_statements (id uuid primary key default gen_random_uuid(),business_unit_id uuid not null references vgroup.business_units(id),owner_id uuid not null references hospitality.owners(id),period_start date not null,period_end date not null,currency text not null default 'EGP',gross_revenue numeric(18,2) not null default 0,total_expenses numeric(18,2) not null default 0,total_fees numeric(18,2) not null default 0,net_payable numeric(18,2) not null default 0,status text not null default 'draft' check (status in ('draft','final','sent','paid')),generated_at timestamptz not null default now(),sent_at timestamptz,unique(owner_id,period_start,period_end),check (period_end>=period_start));

create index on hospitality.properties(owner_id); create index on hospitality.assets(property_id); create index on hospitality.vendors(business_unit_id); create index on hospitality.channel_connections(property_id); create index on hospitality.reservations(property_id,check_in,check_out); create index on hospitality.reservations(business_unit_id,status); create index on hospitality.invoices(property_id,status); create index on hospitality.invoices(owner_id); create index on hospitality.invoices(vendor_id); create index on hospitality.invoices(expense_category_id); create index on hospitality.work_orders(property_id,status); create index on hospitality.work_orders(vendor_id); create index on hospitality.purchase_orders(vendor_id,status); create index on hospitality.purchase_orders(property_id); create index on hospitality.purchase_orders(work_order_id); create index on hospitality.inventory_items(property_id); create index on hospitality.inventory_movements(item_id,created_at); create index on hospitality.contracts(owner_id,status); create index on hospitality.contracts(property_id,status); create index on hospitality.owner_statements(owner_id,period_start,period_end);

alter table hospitality.owners enable row level security; alter table hospitality.properties enable row level security; alter table hospitality.assets enable row level security; alter table hospitality.vendors enable row level security; alter table hospitality.expense_categories enable row level security; alter table hospitality.channel_connections enable row level security; alter table hospitality.reservations enable row level security; alter table hospitality.invoices enable row level security; alter table hospitality.work_orders enable row level security; alter table hospitality.purchase_orders enable row level security; alter table hospitality.inventory_items enable row level security; alter table hospitality.inventory_movements enable row level security; alter table hospitality.contracts enable row level security; alter table hospitality.owner_statements enable row level security;
revoke all on all tables in schema hospitality from anon, authenticated; grant all on all tables in schema hospitality to service_role; grant all on all sequences in schema hospitality to service_role;
create policy owners_server_only on hospitality.owners for all to authenticated using(false) with check(false); create policy properties_server_only on hospitality.properties for all to authenticated using(false) with check(false); create policy assets_server_only on hospitality.assets for all to authenticated using(false) with check(false); create policy vendors_server_only on hospitality.vendors for all to authenticated using(false) with check(false); create policy expense_categories_server_only on hospitality.expense_categories for all to authenticated using(false) with check(false); create policy channel_connections_server_only on hospitality.channel_connections for all to authenticated using(false) with check(false); create policy reservations_server_only on hospitality.reservations for all to authenticated using(false) with check(false); create policy invoices_server_only on hospitality.invoices for all to authenticated using(false) with check(false); create policy work_orders_server_only on hospitality.work_orders for all to authenticated using(false) with check(false); create policy purchase_orders_server_only on hospitality.purchase_orders for all to authenticated using(false) with check(false); create policy inventory_items_server_only on hospitality.inventory_items for all to authenticated using(false) with check(false); create policy inventory_movements_server_only on hospitality.inventory_movements for all to authenticated using(false) with check(false); create policy contracts_server_only on hospitality.contracts for all to authenticated using(false) with check(false); create policy owner_statements_server_only on hospitality.owner_statements for all to authenticated using(false) with check(false);
